module.exports = /*#__PURE__*/JSON.parse('{"id":"theory/musical-scale-fundation","title":"音階基礎","description":"西洋樂理以巴哈十二平均律為基礎。平均律定義了音階的物理關係，將倍數頻率 (ex：220Hz - 440Hz) 以指數關係分成十二個半音，我們又依據聽覺的協和度定義了音程關係，以音程關係加以排列組合，形成各式各樣的聲響特色、顏色，經由先知們整理過後，形成我們目前使用的音階系統。\\n","source":"@site/docs/theory/musical-scale-fundation.md","sourceDirName":"theory","slug":"/theory/musical-scale-fundation","permalink":"/theory/musical-scale-fundation","draft":false,"unlisted":false,"tags":[{"inline":true,"label":"★★★","permalink":"/tags/★★★"},{"inline":true,"label":"音階","permalink":"/tags/音階"},{"inline":true,"label":"調式","permalink":"/tags/調式"}],"version":"current","frontMatter":{"title":"音階基礎","description":"西洋樂理以巴哈十二平均律為基礎。平均律定義了音階的物理關係，將倍數頻率 (ex：220Hz - 440Hz) 以指數關係分成十二個半音，我們又依據聽覺的協和度定義了音程關係，以音程關係加以排列組合，形成各式各樣的聲響特色、顏色，經由先知們整理過後，形成我們目前使用的音階系統。\\n","date":"2006-12-04T00:00:00.000Z","tags":["★★★","音階","調式"],"weight":10},"sidebar":"tutorialSidebar","previous":{"title":"調式概念","permalink":"/theory/musical-mode"},"next":{"title":"升降記號","permalink":"/theory/note-signature/"}}');

